import{_ as s,C as a,o as r,c as n,j as e,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/desktop-runs-tray.png",u="/screenshots/desktop-run-live-code.png",b=JSON.parse(`{"title":"Local runs tray","description":"The desktop app's Local runs tray: each Playwright run it starts, counted as the run's own process counts its tests, Stop and Force stop, a failed run's end leading to its first failure, its output to filter and copy, and the runs that ended kept through a reload and a restart.","frontmatter":{"title":"Local runs tray","description":"The desktop app's Local runs tray: each Playwright run it starts, counted as the run's own process counts its tests, Stop and Force stop, a failed run's end leading to its first failure, its output to filter and copy, and the runs that ended kept through a reload and a restart.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/local-runs-tray.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/local-runs-tray.html"}],["meta",{"property":"og:title","content":"Local runs tray | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The desktop app's Local runs tray: each Playwright run it starts, counted as the run's own process counts its tests, Stop and Force stop, a failed run's end leading to its first failure, its output to filter and copy, and the runs that ended kept through a reload and a restart."}]]},"headers":[],"relativePath":"features/local-runs-tray.md","filePath":"features/local-runs-tray.md","lastUpdated":1795720683000}`),p={name:"features/local-runs-tray.md"};function c(g,t,w,f,m,y){const o=a("Needs");return r(),n("div",null,[t[0]||(t[0]=e("h1",{id:"local-runs-tray",tabindex:"-1"},[i("Local runs tray "),e("a",{class:"header-anchor",href:"#local-runs-tray","aria-label":'Permalink to "Local runs tray"'},"​")],-1)),h(o,{desktop:""}),t[1]||(t[1]=l('<p>The <strong>Local runs</strong> tray of the <a href="./desktop.html">desktop app</a> lists every run the app starts: a <strong>Re-run</strong>, a reproduction, a bisect, a <a href="./flake-lab.html">Flake Lab</a> run, a bug report&#39;s run, a run an agent started. It is docked at the bottom of the window, under the page, and opens as a run starts and at each stop. Drag its top edge to resize it, or <strong>Maximize</strong> it; the window remembers its height. While it is open, the run page&#39;s <strong>On your machine</strong> card points to it. <strong>Local runs</strong>, at the foot of the sidebar, opens and closes it, and so do <code>g</code> then <code>t</code>. Closing it stops nothing. This page is about the runs the tray lists: how far each is, <strong>Stop</strong>, <strong>Run again</strong>, the code their stops make, their output, a reload and a restart. Each run&#39;s workers, their stops and their page: <a href="./desktop-runs.html">Desktop app runs</a>.</p><figure><img src="'+d+'" alt="The desktop app&#39;s window, the Local runs tray docked under the run page: on its left three runs, the newest counted 5 of 12 tests, 1 failed, and waiting at a stop; on its right that run&#39;s worker stopped at its page.pause() with Resume, Step and Finish and its page"><figcaption>A run that goes on, counted as its own process counts its tests.</figcaption></figure><h2 id="each-run" tabindex="-1">Each run <a class="header-anchor" href="#each-run" aria-label="Permalink to &quot;Each run&quot;">​</a></h2><p>A run says how far it is as its own process counts its tests: <strong>5 of 12 tests · 1 failed</strong>, a test held at its failure among the failed, then the flaky ones and those <a href="./end-the-test.html">ended at a stop</a>. Its run button on the page and the sidebar&#39;s entry, <strong>1 local run</strong> while it goes on, count the same. Before its first test, and with a reporter that does not count, the run counts the results Playwright prints.</p><p>Once it reported to the app, a run links <strong>Open run #N</strong>, and <strong>Compare with run #N</strong> when its tests come from another run. A failed one leads to its failure: <strong>Open the failure</strong>, on the run and in the message at its end, opens the page of its first failed test, the one its process named first; the run&#39;s page when the run names none. A run of several Playwright projects reports one run for each: the failure is the first one of the first project that failed, in that project&#39;s run. <strong>Run again</strong> starts an ended run as it ran, with its options and its <a href="./watch-a-run.html#hold-failures"><strong>Hold failures</strong></a>.</p><p><strong>Stop</strong> ends a run as <code>Ctrl+C</code> would in a terminal: Playwright stops its workers and the reporter still sends the run&#39;s end. While it winds down, the button gives way to <strong>Force stop</strong>, which kills the process at once, beside <strong>Ends within 10 s</strong>, after which the app kills it anyway. Force stop takes no click for a moment, so a double-click only stops. <a href="./piwi-runner.html">Piwi Runner</a> stops a run the same way.</p><p>An ended run lists the tests it failed on above its output, failed then flaky, each with its project, the first lines of its error and its file, to open in your editor. They come from its runs on the dashboard, else from its output. Each has <strong>Open</strong>; a test of a run of tests also has <strong>Run again</strong>, for that test alone, and <strong>Run again with Hold failures</strong> when the run can hold.</p><p>An ended run&#39;s <strong>More actions</strong> menu holds <strong>Copy the command</strong>, for a run of tests: the command that runs them in your terminal, as the run button&#39;s <strong>Copy as command</strong> writes it, and <strong>Remove from the list</strong>; <strong>Clear finished runs</strong> removes all of them. While the tray is closed, a run that ends marks the sidebar&#39;s <strong>Local runs</strong> with a dot, red when it failed, until you open the tray.</p><p><strong>Open the run in a separate window</strong>, the run&#39;s window button, shows the whole run in a window of its own: its <strong>Stop</strong> or <strong>Run again</strong>, <strong>Hold failures</strong>, links, workers, failures and output. <strong>Run again</strong> there runs in that window; a link opens in the app&#39;s window. <strong>Show in the tray</strong>, closing the window, or that button, now <strong>Show the run here</strong>, brings it back. The window stays open whatever page the app shows and through a reload, and closes as its run leaves the tray and with the app; one the reloaded tray shows no run in closes.</p><p>A reproduction, a bisect step or a Flake Lab run that went to the editor open on the project&#39;s linked folder (<a href="./desktop-runs.html#a-reproduction-in-your-editor">A reproduction in your editor</a>) says where its tests wait, <strong>In Visual Studio Code</strong>, read only, with no <strong>Hold failures</strong>: the editor holds them. Its line is marked while one waits, <strong>Stop</strong> still ends it, and it ends with its own verdict.</p><h2 id="stops-while-you-look-elsewhere" tabindex="-1">Stops while you look elsewhere <a class="header-anchor" href="#stops-while-you-look-elsewhere" aria-label="Permalink to &quot;Stops while you look elsewhere&quot;">​</a></h2><p>The tray opens at each stop, where a headless test waits for you. With the window in the background, the system tells you of a failure or a <code>page.pause()</code>, never of a step or a pause you asked for. The window listens on every page, again as soon as it reloads while a run of the app goes on. On a page without the tray (an analytics dashboard in TV mode, an error page), the system tells you of every stop, whatever the window shows, and no failure is held; a <code>page.pause()</code>, a step or a breakpoint waits until the tray shows it again, or <a href="./runs-window.html">Piwi Picker&#39;s Runs window</a> or <a href="./desktop-runs.html#for-agents">an agent</a> answers it. With no run of the app going on, the window stops listening, and a stop goes on at once.</p><h2 id="the-runs-list" tabindex="-1">The runs list <a class="header-anchor" href="#the-runs-list" aria-label="Permalink to &quot;The runs list&quot;">​</a></h2><p>On its left (a select in a narrow window), the tray lists <strong>Running now</strong>, <strong>Started in another window</strong>, then <strong>Finished</strong>. A line of its own says how its run stands and how long it ran; any line is marked while a test waits at a stop. A click shows the run on the right: its command, actions, links, workers, failures and output. A run that starts or stops is shown, unless you are working in the run shown.</p><h2 id="code-from-the-runs" tabindex="-1">Code from the runs <a class="header-anchor" href="#code-from-the-runs" aria-label="Permalink to &quot;Code from the runs&quot;">​</a></h2><p>The app holds no editor, so the code a stop of its runs makes comes to the tray, under <strong>Code from the runs</strong>:</p><ul><li><strong>Assert a region</strong> picks a region of the page, once you watch a headless stop live: its ARIA snapshot becomes a <code>toMatchAriaSnapshot</code> check.</li><li><strong>Mock a request</strong> lists the page&#39;s fetch and XHR responses, credentials hidden: the one you choose becomes a <code>page.route</code>, with what to review in it.</li><li><strong>A locator picked</strong>, on the image or with the pause bar&#39;s <strong>Pick a locator</strong>, shows with the line it was picked for.</li><li><strong>An agent&#39;s code</strong> (<code>code_write</code>) comes here too (<a href="./desktop-runs.html#for-agents">for agents</a>).</li></ul><p>Each code shows the line it goes above and, apart, its import lines, each with <strong>Copy</strong>, made from the file as it is on disk in the folder linked to the project.</p><figure><img src="'+u+'" alt="Code from the runs in the desktop app&#39;s tray: a mocked request, the page.route call to write above tests/checkout.spec.ts:18, with Copy"><figcaption>A mocked request, as code to copy above the stopped line.</figcaption></figure><h2 id="its-output" tabindex="-1">Its output <a class="header-anchor" href="#its-output" aria-label="Permalink to &quot;Its output&quot;">​</a></h2><p>Each run shows its output under its workers, in Playwright&#39;s terminal colors, following its newest line until you scroll up; <strong>Go to the latest line</strong> follows it again. Above it, a field keeps only the lines holding what you type, case and accents ignored; <strong>Go to the first error</strong> scrolls to the first failure Playwright printed; a toggle wraps long lines; and <strong>Copy output</strong> copies every line the tray keeps, without the colors. Its corner drags it taller.</p><h2 id="a-reload" tabindex="-1">A reload <a class="header-anchor" href="#a-reload" aria-label="Permalink to &quot;A reload&quot;">​</a></h2><p>A reload of the window keeps the tray&#39;s runs. A run still going is followed again: its output goes on, with its <strong>Hold failures</strong>, its separate window, and how far each of its ended projects came, as you left them. A run whose step ended during the reload ends with that step&#39;s exit code, and goes on to its next step if it has one; a reproduction, a bisect or a Flake Lab job that ended meanwhile still records its verdict, once. A run of tests that was starting, its first Playwright project or its next, goes on with the one the app started. Any other run that was starting as the window reloaded ends, saying so: run it again. What the run printed while the window reloaded is lost, and the tray keeps the last 300 lines of each run&#39;s output through a reload.</p><p>The last 15 runs that ended outlive a restart of the app, with their last 300 lines of output, <strong>Run again</strong> and their links. Each shows how long it took instead of its counts.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One window&#39;s runs.</strong> Another window of the app lists its own; this tray lists them under <strong>Started in another window</strong>, their workers shown as you choose one or a test of theirs stops.</li><li><strong>A run that reports to the team instance</strong> (a run it asked for) has no <strong>Open run #N</strong>, <strong>Compare with run #N</strong> or <strong>Open the failure</strong> here: under its workers, <strong>Run #78 · Open</strong> opens its page on the instance in your browser.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop-runs.html">Desktop app runs</a>: each worker, its stops, its page and the code a stop makes.</li><li><a href="./desktop.html">Desktop app</a>: what it runs, and how it links a project to its folder.</li><li><a href="./share-live.html">Share a local run live</a>: let a teammate watch a run of the tray.</li></ul>',28))])}const A=s(p,[["render",c]]);export{b as __pageData,A as default};
